-- Queer Atlas: Split, Nantes, Strasbourg, Merida (Yucatan) and San Sebastian.
-- Current official/community sources checked 2026-08-27. Idempotent.

begin;

alter table if exists public.places add column if not exists venue_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.services add column if not exists service_intel jsonb not null default '{}'::jsonb;

do $qa_require_qari$
declare k text;
begin
  foreach k in array array['country:croatia','country:france','country:mexico','country:spain'] loop
    if not exists(select 1 from public.qa_qari_profiles where destination_key=k and scope_type='country' and is_published=true) then
      raise exception 'Published QARI profile % is required before this city batch can run.', k;
    end if;
  end loop;
end;
$qa_require_qari$;

with src as (
 select * from jsonb_to_recordset($qa_cities$
[
 {"slug":"split","name":"Split","title":"Queer Split","country":"Croatia","country_code":"HR","latitude":43.50813,"longitude":16.44019,"timezone":"Europe/Zagreb","vibe":"Adriatic, creative and increasingly visible","local_mood":"Split's queer life is programme-led rather than concentrated in a permanent gay district: the LGBT Centre, youth culture, drag collectives and Pride temporarily connect the old city with Dom mladih.","queer_status":"Croatian partnership recognition and anti-discrimination rules provide a legal base, while the city's fifteen-year Pride history sits beside documented pressure and uneven everyday openness.","crowd_profile":"Local LGBTIQ+ organisers, students, artists, drag audiences, summer visitors and allies meet through different community and cultural programmes.","introduction":"Split should be read through its calendar, not through an inflated bar count. LGBT Centar Split is the community anchor, Klub Kocka hosts recurring queer performance and Pride events, and Academia Club Ghetto contributes an alternative cultural room used by the official Pride programme. Split Pride's 2026 month included eighteen cultural, educational and social events before the 27 June march.","guide_items":[{"title":"About","text":"Croatia's second city combines a globally busy historic centre with a small, organised queer community. Permanent infrastructure is limited, but Pride, the LGBT Centre and drag-led programming create a real local network."},{"title":"Districts","text":"The LGBT Centre is close to the old town on Kralja Tomislava; Klub Kocka sits in Dom mladih east of the centre. Pride programmes also use Đardin, Ghetto and other cultural spaces, so current organiser maps matter."},{"title":"Safety","text":"Tourist Split is generally navigable, but public comfort varies by crowd and visibility. Use verified transport after late events, avoid isolated beach approaches after dark and follow local Pride guidance."},{"title":"Nightlife","text":"Kocka is an alternative cultural club rather than a nightly gay venue; queer dates are programme-specific. Ghetto is mixed and artistic. Check Split Pride and LGBT Centre channels instead of relying on stale gay-bar directories."},{"title":"Cost","text":"Summer accommodation and waterfront prices rise sharply. Central walking is practical, while late transport and beach access need planning. Community activities may be free; club and drag events set their own admission."}],"guide_sources":[{"label":"Split Pride 2026 official tourism notice","url":"https://visitsplit.com/index.php/hr/8032/split-pride-najava-programa-mjeseca-ponosa-2026"},{"label":"LGBT Centre Split","url":"https://lgbtcentarsplit.org/ko-smo-di-smo/"},{"label":"Klub Kocka official channels","url":"https://linktr.ee/kum.kocka"}],"safety_context":"Split has a durable Pride and community centre but a smaller permanent scene than its tourism volume suggests. Confirm programme locations, respect community-space privacy and apply ordinary late-night and coastal safety awareness.","qari_key":"country:croatia"},
 {"slug":"nantes","name":"Nantes","title":"Queer Nantes","country":"France","country_code":"FR","latitude":47.21837,"longitude":-1.55362,"timezone":"Europe/Paris","vibe":"civic, artistic and community-connected","local_mood":"Nantes combines a long-running LGBTQIA+ centre and Pride with mixed bars, queer cultural projects and a strong municipal equality programme rather than one sealed-off gay quarter.","queer_status":"France supplies marriage equality and broad discrimination protections; locally, NOSIG provides practical support while the city publicly funds visibility, education and anti-discrimination work.","crowd_profile":"Queer residents across generations, students, trans and non-binary groups, asylum seekers, artists, gay nightlife regulars and allies use different parts of the network.","introduction":"NOSIG is the organising and support backbone of queer Nantes, with thirty years of community work, health information and Pride coordination. Le Petit Marais provides late dancing, while Le Montecito offers an earlier gay-friendly cocktail-bar rhythm with cabaret and themed dates. Pride Nantes and CinéPride extend visibility into streets and cinemas each June.","guide_items":[{"title":"About","text":"Nantes has a substantial civic queer ecosystem whose credibility comes from NOSIG, annual Pride, film culture and multiple social formats rather than from counting every progressive bar as LGBTQ+ specific."},{"title":"Districts","text":"Central nightlife clusters around Commerce, Kervégan and Duquesne. NOSIG's centre is south of the Loire on Rue Magdeleine, so tram and walking routes connect community support with the central evening circuit."},{"title":"Safety","text":"French law is protective, but discrimination and late-night incidents still occur. Keep normal city awareness, use NOSIG for current community guidance and do not treat a welcoming district as risk-free."},{"title":"Nightlife","text":"Start earlier at Montecito for cocktails and programmed cabaret, then use Le Petit Marais for a later dance floor. Queer cultural nights rotate, so NOSIG and organiser calendars remain more reliable than static lists."},{"title":"Cost","text":"Nantes is usually less expensive than Paris but Pride and major cultural weekends lift hotel demand. Public transport and a compact centre reduce taxi dependence; individual shows and clubs set separate prices."}],"guide_sources":[{"label":"NOSIG official","url":"https://www.nosig.fr/"},{"label":"Nantes municipal LGBTQIA+ programme","url":"https://metropole.nantes.fr/dossier-lgbtqia-un-mois-contre-les-discriminations"},{"label":"France Tourism Pride calendar","url":"https://www.france.fr/fr/article/lgbt-france-hotels-bars-evenements/"}],"safety_context":"Nantes has mature community support and visible municipal engagement. Visitors should still distinguish nightlife from support services, verify event access and use ordinary late-night transport care.","qari_key":"country:france"},
 {"slug":"strasbourg","name":"Strasbourg","title":"Queer Strasbourg","country":"France","country_code":"FR","latitude":48.58392,"longitude":7.74553,"timezone":"Europe/Paris","vibe":"European, multilingual and quietly expressive","local_mood":"Strasbourg's scene balances an all-identities queer bar, a strong inter-association centre and a large annual visibility march within a compact, internationally minded city.","queer_status":"France's national protections are reinforced by municipal symbolism, an official LGBTQIA+ rights path and La Station's legal, health, social and cultural support.","crowd_profile":"French, German and international residents, students, EU workers, trans and non-binary communities, queer families and mixed-age bar crowds overlap.","introduction":"La Station is the clearest community doorway, providing free social events, a library, café and specialist support behind the cathedral. Canapé Queer is the dedicated all-identities evening room, combining cocktails, queer culture and local products. Strasbourg's Marche des Visibilités and municipal rainbow-rights path give the network a public civic dimension.","guide_items":[{"title":"About","text":"Strasbourg's queer identity is less about a dense club strip than about community infrastructure, cross-border culture and visible municipal commitment. Its compact centre makes those layers easy to combine."},{"title":"Districts","text":"La Station and Canapé Queer are both in the cathedral/Austerlitz side of the historic centre. Pride activity expands across central public space, while trams simplify access from station and outer districts."},{"title":"Safety","text":"The centre is generally straightforward, but national protection does not erase harassment. La Station offers local legal and support routes, and visitors should keep ordinary late-night awareness around transport hubs."},{"title":"Nightlife","text":"Canapé Queer is the strongest verified dedicated bar. Much of the wider queer calendar is event-led through La Station, drag organisers and mixed cultural venues; confirm the actual host before travelling."},{"title":"Cost","text":"Hotel prices climb during EU sessions, Christmas markets and large events. Trams and walking contain transport costs; La Station activities are commonly free while commercial nights price independently."}],"guide_sources":[{"label":"La Station LGBTI official","url":"https://www.lastation-lgbti.eu/"},{"label":"Strasbourg LGBTQIA+ rights path","url":"https://www.strasbourg.eu/chemin-droits-lgbtqia"},{"label":"France Tourism Pride calendar","url":"https://www.france.fr/fr/article/lgbt-france-hotels-bars-evenements/"}],"safety_context":"Strasbourg combines strong legal context with active local support and civic visibility. Use La Station for current help, confirm event-specific access and retain normal central-city care at night.","qari_key":"country:france"},
 {"slug":"merida","name":"Mérida","title":"Queer Mérida","country":"Mexico","country_code":"MX","latitude":20.96737,"longitude":-89.62370,"timezone":"America/Merida","vibe":"Yucatecan, colourful and community-growing","local_mood":"Mérida mixes drag-led nightlife, queer-owned hospitality, municipal inclusion work and Pride-era cultural programming in a city where discretion and public visibility coexist.","queer_status":"Yucatán recognises equal marriage and promotes LGBTQ+ tourism, while lived acceptance remains uneven across families, institutions and neighbourhoods; municipal Mérida Diversa provides a concrete local route.","crowd_profile":"Local gay men, lesbians, trans and non-binary people, drag audiences, artists, Mexican visitors, international residents and allies meet across distinct venues.","introduction":"DIX is the clearest current queer nightlife anchor, with YucaDrag shows and a stated safe-space purpose. Bernardette adds large staged cabaret, while community-friendly cafés and cultural centres broaden the map. Mérida Diversa coordinates municipal inclusion and June programming, and Yucatán's tourism authority documents trained hotels and LGBTQ+ travel partners.","guide_items":[{"title":"About","text":"Mérida's queer visibility is growing through drag, hospitality, public programming and organised community work. The city should not be presented as uniformly accepting simply because it is calmer than many Mexican metros."},{"title":"Districts","text":"The historic centre around Santa Lucía, Paseo de Montejo and Mejorada contains the clearest evening and cultural stops. Mérida Diversa operates east of the core; rides are useful in heat and after late closing."},{"title":"Safety","text":"Yucatán is often marketed as comparatively secure, but LGBTQ+ travellers still need identity-aware judgement. Use registered transport late, protect against heat, and seek local advice for trans-specific or family-related concerns."},{"title":"Nightlife","text":"DIX centres drag, pop and reggaetón with table reservations; Bernardette is a seated production show. These are not interchangeable with quieter queer-friendly cafés, and cover or booking rules change by programme."},{"title":"Cost","text":"Local drinks and transport can be moderate, while boutique hotels and holiday dates vary widely. Air conditioning, ride costs and event reservations should be included in planning."}],"guide_sources":[{"label":"Yucatán LGBTQ tourism","url":"https://yucatan.travel/turismo-lgbtq/"},{"label":"Mérida Diversa official","url":"https://merida.gob.mx/meridadiversa/quienes-somos.php"},{"label":"Yucatán Today current LGBTQ venues","url":"https://yucatantoday.com/en/blog/merida-lgbtq-places-to-visit-to-celebrate"}],"safety_context":"Mérida has real municipal and tourism-sector inclusion work, but visitors should not confuse promotional safety claims with identical lived experience for every identity. Verify transport, opening hours and local community guidance.","qari_key":"country:mexico"},
 {"slug":"san_sebastian","name":"San Sebastián","title":"Queer San Sebastián","country":"Spain","country_code":"ES","latitude":43.31833,"longitude":-1.98123,"timezone":"Europe/Madrid","vibe":"coastal, gastronomic and institutionally inclusive","local_mood":"Donostia's queer life is woven into a broadly social city through Gehitu, public services, Pride visibility, film culture and a flagship LGBTQIA-focused hotel rather than a large gay-bar strip.","queer_status":"Spain provides a strong national legal baseline; Basque institutions add Berdindu support, Queer Destinations training and municipal monitoring of LGTBI-phobic incidents.","crowd_profile":"Basque LGBTQ+ residents, food and film travellers, surfers, students, older community members, international couples and allies meet through associations and citywide culture.","introduction":"Gehitu has anchored Basque LGBTQ+ rights, health, education and culture from Donostia for decades, while Berdindu provides a public information and support route. Axel is the city's most explicit LGBTQIA-focused stay, and the Sebastiane film prize connects queer representation to the international film festival. Older gay-bar listings are deliberately excluded where current evidence confirms closure.","guide_items":[{"title":"About","text":"San Sebastián is highly integrated rather than built around a commercial gayborhood. Its strongest signals are community organisations, public services, certified hospitality and queer film culture."},{"title":"Districts","text":"Gehitu is in Gros on Paseo Colón; Axel and several hotels sit around Centro and Amara. Parte Vieja remains central for food and mixed nightlife, while Berdindu's Gipuzkoa office is west in Antiguo."},{"title":"Safety","text":"Spain and the Basque Country offer strong protections, but the city records and responds to LGTBI-phobic incidents rather than claiming zero risk. Use Berdindu or Gehitu for support and normal coastal-city awareness at night."},{"title":"Nightlife","text":"Dedicated bar information changes quickly and former venues have closed. Treat current community and event calendars as authoritative; do not travel to Txirula or Dioni's based on old directory pages."},{"title":"Cost","text":"Accommodation and dining can be expensive during summer, festivals and major gastronomic dates. The centre is walkable, and buses connect Antiguo and Gros without relying on late taxis."}],"guide_sources":[{"label":"Basque LGBTQ tourism and certified providers","url":"https://turismo.euskadi.eus/webtur00-landing/es/contenidos/recurso_tecnico/aa30_lgbtq/es_def/lgbtq_v2.html"},{"label":"Gehitu official","url":"https://www.gehitu.org/"},{"label":"Berdindu official","url":"https://www.euskadi.eus/gobierno-vasco/-/que-es-berdindu/"}],"safety_context":"Donostia combines strong Spanish protections with local reporting, community support and trained tourism services. Use current sources because the small commercial scene changes, and distinguish public support services from tourist venues.","qari_key":"country:spain"}
]
$qa_cities$) c(slug text,name text,title text,country text,country_code text,latitude double precision,longitude double precision,timezone text,vibe text,local_mood text,queer_status text,crowd_profile text,introduction text,guide_items jsonb,guide_sources jsonb,safety_context text,qari_key text)
)
insert into public.qa_cities(slug,name,title,country,country_code,latitude,longitude,map_confirmed,timezone,vibe,local_mood,queer_status,crowd_profile,introduction,guide_items,guide_sources,guide_checked_at,safety_context,qari_destination_key,qari_score,qari_summary,qari_confidence,status,updated_at)
select c.slug,c.name,c.title,c.country,c.country_code,c.latitude,c.longitude,true,c.timezone,c.vibe,c.local_mood,c.queer_status,c.crowd_profile,c.introduction,c.guide_items,c.guide_sources,date '2026-08-27',c.safety_context,q.destination_key,q.qari_score,q.summary,q.confidence,'published',timezone('utc',now())
from src c cross join lateral (select destination_key,qari_score,summary,confidence from public.qa_qari_profiles where destination_key=c.qari_key and scope_type='country' and is_published=true order by reviewed_at desc nulls last limit 1) q
on conflict(slug) do update set name=excluded.name,title=excluded.title,country=excluded.country,country_code=excluded.country_code,latitude=excluded.latitude,longitude=excluded.longitude,map_confirmed=true,timezone=excluded.timezone,vibe=excluded.vibe,local_mood=excluded.local_mood,queer_status=excluded.queer_status,crowd_profile=excluded.crowd_profile,introduction=excluded.introduction,guide_items=excluded.guide_items,guide_sources=excluded.guide_sources,guide_checked_at=excluded.guide_checked_at,safety_context=excluded.safety_context,qari_destination_key=excluded.qari_destination_key,qari_score=excluded.qari_score,qari_summary=excluded.qari_summary,qari_confidence=excluded.qari_confidence,status='published',updated_at=excluded.updated_at;

with src as (
 select * from jsonb_to_recordset($qa_places$
[
 {"name":"Klub Kocka","city":"split","type":"club","description":"An independent youth and culture club inside Dom mladih that hosts concerts, exhibitions, alternative dance nights and recurring official Split Pride programming. It is queer-relevant on verified programme dates rather than a permanent gay club.","hours":"Programme-led; use the official Kocka channels for each event.","link":"https://linktr.ee/kum.kocka","location":"Ulica Slobode 28, 21000 Split, Croatia","lat":43.512499,"lng":16.450435,"vibe":"alternative cultural club with recurring drag, Pride and queer community nights","intel":{"queue_wait":"Ticketed concerts and Pride afterparties can fill the room; ordinary programme nights use event-specific entry rather than a permanent club queue.","best_nights":"Choose an event explicitly published by Split Pride, Drag Kokošinjac or Kocka instead of assuming every Kocka night is queer.","crowd_mix":"Local queer people, students, alternative-music audiences, artists and allies vary substantially with each promoter.","dress_code":"Alternative casual and expressive event clothing fits; individual concerts may set age, ticket or safety rules.","staff_inclusivity":"Repeated hosting in the official 2026 Split Pride programme supports a queer-relevant classification without relabelling the whole venue.","source_urls":["https://linktr.ee/kum.kocka","https://visitsplit.com/index.php/hr/8032/split-pride-najava-programa-mjeseca-ponosa-2026"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"LGBT Centre Split","city":"split","type":"cafe","description":"A physical socio-cultural centre managed by Split LGBTQ+ organisations around queer-feminist, anti-violence and inclusive values. It hosts workshops, screenings, talks and community gatherings rather than operating as a tourist café.","hours":"Activity-led; confirm each programme or contact the centre before visiting.","link":"https://lgbtcentarsplit.org/","location":"Ulica kralja Tomislava 8, 21000 Split, Croatia","lat":43.509619,"lng":16.439225,"vibe":"community-run queer cultural room for learning, connection and local organising","intel":{"queue_wait":"There is no entertainment door; workshops and support-oriented gatherings may require registration or intentionally limited attendance.","best_nights":"Use the centre's current calendar for screenings, workshops and community socials, especially during Pride Month.","crowd_mix":"Local LGBTIQ+ residents, organisers, young people, artists and invited allies use the space across different formats.","dress_code":"No dress code applies; privacy, consent and respect for a community rather than tourist environment are essential.","staff_inclusivity":"The centre is explicitly governed through inclusivity, non-violence, anti-fascism and queer-feminist values.","source_urls":["https://lgbtcentarsplit.org/ko-smo-di-smo/","https://visitsplit.com/index.php/hr/8032/split-pride-najava-programa-mjeseca-ponosa-2026"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Le Petit Marais","city":"nantes","type":"club","description":"A long-running late bar and dance venue on Rue Kervégan with a recognised LGBTQ+ audience and a documented 2026 Pride afterparty. Its 22:00 opening positions it as a later stop than Nantes's cocktail bars.","hours":"Tuesday-Saturday 22:00-04:00 according to the current Nantes cultural listing.","link":"https://www.facebook.com/lepetit.marais/","location":"15 Rue Kervégan, 44000 Nantes, France","lat":47.212703,"lng":-1.555800,"vibe":"compact late queer dance bar with multigenerational pop-party energy","intel":{"queue_wait":"The narrow late venue can compress after midnight and after Pride; earlier arrival is easier for first-time orientation.","best_nights":"Friday, Saturday and a specifically published Pride or theme date provide the clearest dance-floor experience.","crowd_mix":"Gay regulars, broader LGBTQ+ groups, mixed-age local friends and Pride visitors share a small central room.","dress_code":"Casual going-out clothing works; bring physical identification and follow any event-specific age or admission notice.","staff_inclusivity":"Its established scene role and documented 2026 Pride afterparty provide stronger evidence than a generic friendly directory label.","source_urls":["https://www.bigcitynantes.fr/lieu/le-petit-marais/","https://www.pagesjaunes.fr/pros/64370351"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Le Montecito","city":"nantes","type":"bar","description":"A self-described gay-friendly cocktail bar serving bespoke drinks, wine and sharing plates, with recurring DJ, open-stage and transformist cabaret programming. Daily afternoon opening makes it a social first stop rather than only a late club.","hours":"Daily 16:00-02:00 according to the official venue site.","link":"https://www.lemontecito.fr/","location":"6 Allée Duquesne, 44000 Nantes, France","lat":47.217501,"lng":-1.556738,"vibe":"welcoming gay-friendly cocktail bar with cabaret, bingo and easy early-evening conversation","intel":{"queue_wait":"Ordinary afternoons are easy; cabaret, bingo and DJ dates can fill tables and deserve a direct reservation enquiry.","best_nights":"Use the official monthly programme for transformist bingo, cabaret and open-stage dates; earlier hours suit conversation.","crowd_mix":"LGBTQ+ regulars, cocktail drinkers, cabaret audiences and mixed local friends create a broad social bar crowd.","dress_code":"Relaxed city clothing and expressive cabaret looks both fit; no formal code is published.","staff_inclusivity":"The venue explicitly identifies as gay-friendly and programmes transformist performance rather than relying only on third-party labelling.","source_urls":["https://www.lemontecito.fr/","https://www.france.fr/fr/article/lgbt-france-hotels-bars-evenements/"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Canapé Queer","city":"strasbourg","type":"bar","description":"An explicitly inclusive queer bar near Place d'Austerlitz built around cocktails, local products, queer music culture and a room open across identities. It offers mocktail variants and recurring themed programming.","hours":"Monday-Wednesday approximately 17:00-01:30; Thursday-Saturday to 04:00; verify current Instagram posts.","link":"https://www.instagram.com/canapequeerstrasbourg/","location":"20 Rue des Couples, 67000 Strasbourg, France","lat":48.578836,"lng":7.753619,"vibe":"all-identities queer cocktail bar balancing conversation, pop culture and late weekend energy","intel":{"queue_wait":"The small room is calmer early and can become dense on Thursday-to-Saturday theme nights; there is no evidence of a routine formal line.","best_nights":"Choose current glitter, open-mic or community programming for the strongest queer-culture expression; earlier evenings suit drinks and conversation.","crowd_mix":"Queer people across genders, local regulars, international visitors and respectful allies share an intentionally non-exclusive bar.","dress_code":"Come-as-you-are and expressive looks fit the concept; no restrictive appearance policy is published.","staff_inclusivity":"The founder explicitly created an inclusive bar valuing queer culture, with products that support LGBTQ+ associations.","source_urls":["https://www.instagram.com/canapequeerstrasbourg/","https://www.topmusic.fr/roland-inside-le-canape-queer","https://www.zut-magazine.com/categorie/a-table/adresses/canape-queer-strasbourg/"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"La Station LGBTI","city":"strasbourg","type":"cafe","description":"Strasbourg and Alsace's inter-association LGBTQIA+ centre, combining a community café, queer library, free social events and legal, listening, health and cultural activities. This physical listing represents its public community room.","hours":"Tuesday-Friday 16:00-20:00; Saturday 10:00-13:00 and 14:00-19:00; event exceptions apply.","link":"https://www.lastation-lgbti.eu/","location":"7 Rue des Écrivains, 67000 Strasbourg, France","lat":48.581651,"lng":7.753312,"vibe":"free community café and resource hub connecting identities, generations and specialist support","intel":{"queue_wait":"Normal public access has no club queue; legal sessions, identity cafés and other groups may use appointments or limited participation.","best_nights":"Consult the official calendar for transfem, aro-ace, 45+ and other community cafés rather than assuming one generic social format.","crowd_mix":"LGBTQIA+ residents across ages and identities, volunteers, people seeking support and invited allies use distinct programmes.","dress_code":"No dress code applies; confidentiality, consent and respect for support-seeking visitors are mandatory.","staff_inclusivity":"La Station is the dedicated regional LGBTQIA+ centre and publishes detailed public access and specialist programme information.","source_urls":["https://www.lastation-lgbti.eu/contact/","https://www.strasbourg.eu/documents/976405/1439068/p9_Flyer%2Breseaudelutte.pdf/840b3cbf-630d-b361-87b3-03407a504edf?t=1616162741043"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"DIX Bar","city":"merida","type":"club","description":"A dedicated LGBTQ+ drag-show bar near Parque Santa Lucía, centred on YucaDrag residents, themed productions, pop and reggaetón. Its own site describes a safe space for celebrating drag and diversity.","hours":"Daily approximately 20:00-02:30; confirm the current programme and reservation slot.","link":"https://dixbar.com/","location":"Calle 53 #495 between 56 and 58, Centro, Mérida, Yucatán, Mexico","lat":20.971925,"lng":-89.620803,"vibe":"high-colour LGBTQ+ drag room with table shows, pop celebration and late dancing","intel":{"queue_wait":"Reservations are the safest route; weekend tables and special guest queens can sell out, with cover varying by programme.","best_nights":"Choose the current YucaDrag cast or guest programme; Friday and especially Saturday are busiest, while some weekdays have no cover.","crowd_mix":"Gay men are prominent alongside broader LGBTQ+ friends, drag fans, local groups and visitors celebrating special occasions.","dress_code":"Colourful nightlife and expressive drag-inspired looks fit; table service and production sightlines matter more than formal clothing.","staff_inclusivity":"DIX explicitly calls itself a safe space for drag and diversity, supported by current first-party programming and local editorial verification.","source_urls":["https://dixbar.com/","https://yucatantoday.com/en/blog/merida-lgbtq-places-to-visit-to-celebrate"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Bernardette Show Bar","city":"merida","type":"club","description":"A staged musical and drag show bar on Paseo de Montejo with a large resident cast, themed productions and table service. It suits visitors seeking a seated spectacle rather than an unstructured dance club.","hours":"Thursday-Saturday 21:00-02:30; current source notes showtime around 22:00.","link":"https://www.instagram.com/bernardette.showbar/","location":"Paseo de Montejo #312, Centro, Mérida, Yucatán, Mexico","lat":20.982760,"lng":-89.618050,"vibe":"theatrical cabaret venue with immersive singers, dancers, drag and celebratory table service","intel":{"queue_wait":"Seating is limited and reservation is specifically recommended; arrive before the published show rather than during the opening number.","best_nights":"Select the advertised tribute or drag cast because each Thursday-to-Saturday production has a different theme.","crowd_mix":"LGBTQ+ audiences, drag fans, birthday groups, couples and wider musical-theatre visitors share a seated show format.","dress_code":"Polished party clothing and expressive looks suit the production; no identity-based code is documented.","staff_inclusivity":"Current local LGBTQ+ editorial coverage places the venue in Mérida's Pride circuit and documents its drag cast directly.","source_urls":["https://yucatantoday.com/en/blog/merida-lgbtq-places-to-visit-to-celebrate","https://www.instagram.com/bernardette.showbar/"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Gehitu Community Centre","city":"san_sebastian","type":"cafe","description":"The Donostia base of Gehitu, the Basque LGBTQI+ association working across rights, culture, health, education, support groups and public visibility. It is a community office and meeting resource rather than commercial hospitality.","hours":"Programme and appointment-led; contact Gehitu before visiting.","link":"https://www.gehitu.org/","location":"Paseo Colón 50, 20002 Donostia / San Sebastián, Spain","lat":43.325089,"lng":-1.974069,"vibe":"long-established Basque LGBTQI+ rights, culture, health and community connection hub","intel":{"queue_wait":"There is no nightlife queue; support, group and project access may require prior contact and should not be interrupted as tourism.","best_nights":"Use Gehitu's current agenda for public cultural or Pride activity; arrange personal support separately.","crowd_mix":"LGBTQI+ residents across generations, volunteers, health users, cultural participants and rights advocates use different services.","dress_code":"No dress code applies; confidentiality and respect for people seeking support are essential.","staff_inclusivity":"Gehitu is a dedicated LGBTQI+ association with documented health, education, cultural and rights functions across Gipuzkoa.","source_urls":["https://www.gehitu.org/","https://www.donostia.eus/barrios/elkartea.nsf/vListadoId/9433AE1D047F456641256743003AB192?OpenDocument=&id=A608306628767&idioma=cas&ord=sector&sf=2"],"updated_at":"2026-08-27T00:00:00Z"}}
]
$qa_places$) p(name text,city text,type text,description text,hours text,link text,location text,lat double precision,lng double precision,vibe text,intel jsonb)
), upd as (
 update public.places t set type=p.type,description=p.description,hours=p.hours,link=p.link,location=p.location,lat=p.lat,lng=p.lng,vibe=p.vibe,vibe_tags=array[]::text[],venue_intel=p.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from src p where lower(trim(t.city))=p.city and lower(trim(t.name))=lower(trim(p.name)) returning t.id
)
insert into public.places(name,city,type,description,hours,link,location,lat,lng,vibe,vibe_tags,venue_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,type,description,hours,link,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from src p where not exists(select 1 from public.places t where lower(trim(t.city))=p.city and lower(trim(t.name))=lower(trim(p.name)));

with src as (
 select * from jsonb_to_recordset($qa_events$
[
 {"name":"Split Pride 2026","city":"split","description":"The fifteenth-anniversary Split Pride month ran from 5 to 27 June 2026 with eighteen cultural, educational and social activities, closing with the Pride March and Kocka afterparty.","link":"https://visitsplit.com/index.php/hr/8032/split-pride-najava-programa-mjeseca-ponosa-2026","date":"2026-06-27","start_date":"2026-06-27T17:00:00+02:00","end_date":"2026-06-27T23:59:00+02:00","location":"Central Split and Klub Kocka, Split, Croatia","lat":43.508130,"lng":16.440190,"vibe":"public anniversary Pride linking local resistance, culture, education and celebration","intel":{"entry_wait":"The public march has no conventional door, while the official afterparty follows Kocka capacity and entry procedures.","best_arrival":"Use the organiser's final assembly notice and arrive before movement begins; treat the afterparty as a separate venue entry.","crowd_mix":"Local LGBTIQ+ communities, activists, artists, students, visitors and allies attend different parts of the month.","dress_code":"Weather-ready Pride clothing and walking shoes suit the march; Kocka applies its own event rules.","host_inclusivity":"The dedicated Pride organiser and official destination listing document the complete 2026 programme and community purpose.","source_urls":["https://visitsplit.com/index.php/hr/8032/split-pride-najava-programa-mjeseca-ponosa-2026","https://www.instagram.com/splitpride/"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Pride Nantes 2026","city":"nantes","description":"The official Nantes Pride took place on 13 June 2026 within a municipal month of LGBTQIA+ education, public visibility and CinéPride programming coordinated with NOSIG.","link":"https://www.nosig.fr/page/3863713-pride-nantes-2026-site-officiel","date":"2026-06-13","start_date":"2026-06-13T12:00:00+02:00","end_date":"2026-06-13T20:00:00+02:00","location":"Central Nantes, France","lat":47.218370,"lng":-1.553620,"vibe":"large civic Pride joining association visibility, public education and city celebration","intel":{"entry_wait":"The public march has no club queue; assembly, security and accessible groups use organiser-specific meeting points.","best_arrival":"Check NOSIG's final route and access notice and arrive before the published assembly time.","crowd_mix":"LGBTQIA+ residents, associations, families, students, artists, visitors and allies create a broad public crowd.","dress_code":"Comfortable Pride expression and weather-ready walking clothes fit; no event-wide appearance code applies.","host_inclusivity":"NOSIG is Nantes's dedicated LGBTQIA+ centre and official Pride organiser, supported by the municipal programme.","source_urls":["https://www.nosig.fr/page/3863713-pride-nantes-2026-site-officiel","https://metropole.nantes.fr/dossier-lgbtqia-un-mois-contre-les-discriminations"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Marche des Visibilités Strasbourg 2026","city":"strasbourg","description":"Strasbourg's 2026 LGBTQIA+ visibility march was scheduled for 20 June as the public centrepiece of the city's Pride season and regional association work.","link":"https://www.france.fr/fr/article/lgbt-france-hotels-bars-evenements/","date":"2026-06-20","start_date":"2026-06-20T14:00:00+02:00","end_date":"2026-06-20T20:00:00+02:00","location":"Central Strasbourg, France","lat":48.583920,"lng":7.745530,"vibe":"regional visibility march bringing rights, community and celebration into European public space","intel":{"entry_wait":"Public assembly replaces a conventional door; crowd flow and security can delay movement near the announced departure.","best_arrival":"Use FestiGays and La Station's final route information and arrive before assembly closes.","crowd_mix":"LGBTQIA+ people across Alsace, associations, students, EU residents, families and allies participate.","dress_code":"Walking shoes, weather layers and Pride expression are appropriate; no general dress code applies.","host_inclusivity":"The march is dedicated to LGBTQIA+ visibility and is independently listed in France's official 2026 tourism calendar.","source_urls":["https://www.france.fr/fr/article/lgbt-france-hotels-bars-evenements/","https://www.lastation-lgbti.eu/"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Agenda Mérida Diversa 2026","city":"merida","description":"Mérida's municipal Pride-month agenda ran from 13 to 28 June 2026 with cultural, educational, community and visibility activities, beginning with the LGBTI+ cultural night Hasta que te conocí.","link":"https://prensa.merida.gob.mx/12374/Ayuntamiento-impulsa-la-Agenda-Merida-Diversa-2026-para-seguir-construyendo-una-ciudad-donde-todas-y-todos-tengan-un-lugar/amp","date":"2026-06-13","start_date":"2026-06-13T18:00:00-06:00","end_date":"2026-06-28T22:00:00-06:00","location":"Multiple municipal venues across Mérida, Yucatán, Mexico","lat":20.967370,"lng":-89.623700,"vibe":"municipal Pride-month programme connecting culture, education, local enterprise and public inclusion","intel":{"entry_wait":"Each activity has separate capacity and registration; the multi-week agenda does not have one admission process.","best_arrival":"Use Mérida Diversa's current channels for the exact venue and timing of each activity.","crowd_mix":"Local LGBTI+ residents, families, artists, students, municipal teams, entrepreneurs and allies attend different sessions.","dress_code":"No programme-wide code applies; heat, rain and the selected indoor or outdoor format determine practical clothing.","host_inclusivity":"The municipal Inclusion and Diversity office explicitly created the agenda to support LGBTI+ visibility, respect and participation.","source_urls":["https://prensa.merida.gob.mx/12374/Ayuntamiento-impulsa-la-Agenda-Merida-Diversa-2026-para-seguir-construyendo-una-ciudad-donde-todas-y-todos-tengan-un-lugar/amp","https://merida.gob.mx/meridadiversa/quienes-somos.php"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Donostia Pride 2026","city":"san_sebastian","description":"Gehitu's 28 June 2026 Pride action brought LGBTQIA+ visibility into Donostia's streets under its annual rights-focused organising, supported by municipal public symbolism and anti-hate measures.","link":"https://www.gehitu.org/","date":"2026-06-28","start_date":"2026-06-28T12:00:00+02:00","end_date":"2026-06-28T20:00:00+02:00","location":"Central Donostia / San Sebastián, Spain","lat":43.318330,"lng":-1.981230,"vibe":"Basque civic Pride joining public visibility, rights and citywide cultural support","intel":{"entry_wait":"Public street activity has no commercial entry; follow the organiser's final assembly and accessibility instructions.","best_arrival":"Confirm the exact meeting point with Gehitu shortly before 28 June and arrive before the public action starts.","crowd_mix":"Basque LGBTQI+ residents, Gehitu members, families, cultural participants, visitors and allies attend.","dress_code":"Comfortable Pride expression and coastal weather layers suit the public programme.","host_inclusivity":"Gehitu is the established Basque LGBTQI+ association and the municipality publicly supports visibility and anti-hate response.","source_urls":["https://www.gehitu.org/","https://www.donostia.eus/es/home"],"updated_at":"2026-08-27T00:00:00Z"}}
