$qa_events$) e(name text,city text,description text,link text,date text,start_date timestamptz,end_date timestamptz,location text,lat double precision,lng double precision,vibe text,intel jsonb)
), upd as (
 update public.events t set description=e.description,link=e.link,date=e.date,start_date=e.start_date,end_date=e.end_date,location=e.location,lat=e.lat,lng=e.lng,vibe=e.vibe,vibe_tags=array[]::text[],event_intel=e.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from src e where lower(trim(t.city))=e.city and lower(trim(t.name))=lower(trim(e.name)) returning t.id
)
insert into public.events(name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,vibe_tags,event_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from src e where not exists(select 1 from public.events t where lower(trim(t.city))=e.city and lower(trim(t.name))=lower(trim(e.name)));

with src as (
 select * from jsonb_to_recordset($qa_services$
[
 {"name":"LGBT Centre Split Community Information","city":"split","type":"other","provider_name":"LGBT Centre Split","contact":"Use the official centre contact and programme channels","booking_link":"https://lgbtcentarsplit.org/","description":"The local LGBTQ+ centre connects people to community activities, queer culture and Split Pride information. Physical attendance depends on the published activity and should not be assumed as unrestricted daily walk-in support.","hours":"Programme-led; contact before visiting.","link":"https://lgbtcentarsplit.org/","location":"Ulica kralja Tomislava 8, 21000 Split, Croatia","lat":43.509619,"lng":16.439225,"vibe":"local queer information, cultural participation and community connection","source":"LGBT Centre Split and official 2026 Split Pride tourism programme; checked 2026-08-27","intel":{"booking_lead_time":"Contact before workshops, support or volunteering because the centre's physical schedule changes with the programme.","best_time":"Use weekday contact and recheck during Pride Month when the activity calendar expands.","client_mix":"Local LGBTIQ+ people, visitors, young people, artists, volunteers and community partners.","preparation":"State whether the request concerns support, access, events, media or volunteering and respect participant confidentiality.","provider_inclusivity":"The centre explicitly operates on queer-feminist, inclusive, non-violent and anti-fascist values.","source_urls":["https://lgbtcentarsplit.org/ko-smo-di-smo/","https://visitsplit.com/index.php/hr/8032/split-pride-najava-programa-mjeseca-ponosa-2026"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"NOSIG Centre LGBTQIA+","city":"nantes","type":"other","provider_name":"NOSIG","contact":"+33 2 40 37 96 37; contact@nosig.fr","booking_link":"https://www.nosig.fr/","description":"Nantes's LGBTQIA+ centre provides reception, rights and health information, discrimination support, community activities and guidance for asylum seekers and families. It also coordinates Pride Nantes.","hours":"Contact the centre for current reception, group and appointment hours.","link":"https://www.nosig.fr/","location":"7 Rue Magdeleine, 44200 Nantes, France","lat":47.204311,"lng":-1.568063,"vibe":"thirty-year community centre joining support, health, rights, memory and social connection","source":"Nantes Métropole association register and NOSIG official site; checked 2026-08-27","intel":{"booking_lead_time":"Contact ahead for individual support, specialised groups or asylum guidance; public activities may use separate registration.","best_time":"Use weekday contact and consult the current agenda before travelling to the centre.","client_mix":"LGBTQIA+ people across identities and ages, families, asylum seekers, people facing discrimination and community volunteers.","preparation":"Explain the type of support required and ask about language, accessibility, confidentiality and documents before an appointment.","provider_inclusivity":"NOSIG is Nantes's dedicated LGBTQIA+ centre with explicitly documented support, health, rights and anti-discrimination functions.","source_urls":["https://metropole.nantes.fr/mes-services-mon-quotidien/espace-associations-nantaises/annuaire-des-associations-nantaises/nosig-centre-lgbtqi-de-nantes","https://www.nosig.fr/"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"La Station LGBTI Support","city":"strasbourg","type":"other","provider_name":"La Station LGBTI","contact":"+33 9 50 51 13 29; contact@lastation-lgbti.eu","booking_link":"https://www.lastation-lgbti.eu/contact/","description":"The regional LGBTQIA+ centre offers legal sessions, listening, health information, identity-specific cafés, cultural activity and referrals alongside its public community room.","hours":"Tuesday-Friday 16:00-20:00; Saturday 10:00-13:00 and 14:00-19:00; specialist sessions vary.","link":"https://www.lastation-lgbti.eu/","location":"7 Rue des Écrivains, 67000 Strasbourg, France","lat":48.581651,"lng":7.753312,"vibe":"free regional LGBTQIA+ support connecting legal, health, social and cultural needs","source":"La Station official contact and Strasbourg anti-discrimination network; checked 2026-08-27","intel":{"booking_lead_time":"General public access follows opening hours, while legal and specialised support can require an appointment.","best_time":"Contact during public hours and name the legal, health, listening or social need so the correct team can respond.","client_mix":"LGBTQIA+ residents, people facing discrimination, trans and aro-ace participants, older adults, families and allies.","preparation":"Bring only relevant documents for a booked legal session and ask how confidentiality and accessibility are handled.","provider_inclusivity":"La Station is the dedicated Strasbourg-Alsace LGBTQIA+ centre and coordinates identity-specific and specialist services.","source_urls":["https://www.lastation-lgbti.eu/contact/","https://www.strasbourg.eu/documents/976405/1439068/p9_Flyer%2Breseaudelutte.pdf/840b3cbf-630d-b361-87b3-03407a504edf?t=1616162741043"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Mérida Diversa","city":"merida","type":"other","provider_name":"Mérida Municipal Inclusion and Diversity Coordination","contact":"+52 999 942 0000 ext. 81800","booking_link":"https://merida.gob.mx/meridadiversa/quienes-somos.php","description":"The municipal Inclusion and Diversity office develops LGBTI+ visibility, equality and anti-discrimination initiatives and publishes the city's current diversity programme and contact routes.","hours":"Monday-Friday 08:00-15:00 according to the official municipal page.","link":"https://merida.gob.mx/meridadiversa/quienes-somos.php","location":"Calle 65 between 42 and 44, Colonia Centro, Mérida, Yucatán, Mexico","lat":20.964900,"lng":-89.609500,"vibe":"municipal inclusion, visibility and rights access for Mérida's LGBTI+ communities","source":"Mérida municipal Inclusion and Diversity office; checked 2026-08-27","intel":{"booking_lead_time":"Call during weekday hours before visiting because programme venues and the correct municipal contact can differ.","best_time":"Use morning municipal hours and follow the official broadcast channel for Pride-month activities.","client_mix":"LGBTI+ residents, families, community organisations, event participants and people seeking municipal orientation.","preparation":"Describe whether the request concerns discrimination, programming, participation or referral and ask about required documentation.","provider_inclusivity":"The office is explicitly mandated to promote LGBTI+ visibility, respect, equal opportunity and freedom from discrimination.","source_urls":["https://merida.gob.mx/meridadiversa/quienes-somos.php","https://prensa.merida.gob.mx/12374/Ayuntamiento-impulsa-la-Agenda-Merida-Diversa-2026-para-seguir-construyendo-una-ciudad-donde-todas-y-todos-tengan-un-lugar/amp"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Gehitu","city":"san_sebastian","type":"other","provider_name":"Gehitu","contact":"+34 607 829 807; info@gehitu.org","booking_link":"https://www.gehitu.org/","description":"The Basque LGBTQI+ association provides rights, health, education, culture, welcome groups and community organising from its Donostia base, including Pride and queer film work.","hours":"Programme and appointment-led; contact before visiting.","link":"https://www.gehitu.org/","location":"Paseo Colón 50, 20002 Donostia / San Sebastián, Spain","lat":43.325089,"lng":-1.974069,"vibe":"established Basque LGBTQI+ support, rights, health and cultural organising","source":"Gehitu official and Donostia municipal association register; checked 2026-08-27","intel":{"booking_lead_time":"Contact before individual support or a group; public Pride and cultural events follow separate published access.","best_time":"Use weekday contact and specify whether the request concerns health, rights, community, film or Pride.","client_mix":"LGBTQI+ people across Gipuzkoa, families, health users, cultural participants, volunteers and rights advocates.","preparation":"Explain the support need and ask about language, confidentiality, accessibility and whether an appointment is required.","provider_inclusivity":"Gehitu is a dedicated LGBTQI+ association with documented work across rights, health, culture, education and support.","source_urls":["https://www.gehitu.org/","https://www.donostia.eus/barrios/elkartea.nsf/vListadoId/9433AE1D047F456641256743003AB192?OpenDocument=&id=A608306628767&idioma=cas&ord=sector&sf=2"],"updated_at":"2026-08-27T00:00:00Z"}},
 {"name":"Berdindu Gipuzkoa","city":"san_sebastian","type":"other","provider_name":"Basque Government","contact":"900 840 128; 688 769 865; berdindu.gipuzkoa@euskadi.eus","booking_link":"https://www.euskadi.eus/gobierno-vasco/-/que-es-berdindu/","description":"The Basque Government's public information and support service for lesbian, gay, trans, bisexual and intersex people, relatives, schools and professionals, available in person, by phone and video call.","hours":"Tuesday-Friday 10:00-13:00; Monday-Friday 16:00-19:00 according to the official service page.","link":"https://www.euskadi.eus/gobierno-vasco/-/que-es-berdindu/","location":"Paseo de Mikeletes 20, 20008 Donostia / San Sebastián, Spain","lat":43.312508,"lng":-2.000573,"vibe":"public confidential LGTBI information, support and anti-discrimination guidance","source":"Basque Government official Berdindu service page; checked 2026-08-27","intel":{"booking_lead_time":"Call or email before an in-person or video appointment, particularly for a specialist, school or professional enquiry.","best_time":"Use the published weekday service windows and state whether the request concerns personal support, family, school or professional guidance.","client_mix":"LGTBI people, relatives, educational communities, professionals and social organisations across Gipuzkoa.","preparation":"Choose a safe communication channel and ask about confidentiality, language, accessibility and any documents relevant to the enquiry.","provider_inclusivity":"Berdindu is the Basque Government's dedicated public LGTBI information and care service with an explicit anti-LGTBIfobia mission.","source_urls":["https://www.euskadi.eus/gobierno-vasco/-/que-es-berdindu/"],"updated_at":"2026-08-27T00:00:00Z"}}
]
$qa_services$) s(name text,city text,type text,provider_name text,contact text,booking_link text,description text,hours text,link text,location text,lat double precision,lng double precision,vibe text,source text,intel jsonb)
), upd as (
 update public.services t set type=s.type,provider_name=s.provider_name,contact=s.contact,booking_link=s.booking_link,description=s.description,hours=s.hours,link=s.link,location=s.location,lat=s.lat,lng=s.lng,vibe=s.vibe,vibe_tags=array[]::text[],source=s.source,"lastChecked"=date '2026-08-27',verified=true,service_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from src s where lower(trim(t.city))=s.city and lower(trim(t.name))=lower(trim(s.name)) returning t.id
)
insert into public.services(name,city,type,provider_name,contact,booking_link,description,hours,link,location,lat,lng,vibe,vibe_tags,source,"lastChecked",verified,service_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,type,provider_name,contact,booking_link,description,hours,link,location,lat,lng,vibe,array[]::text[],source,date '2026-08-27',true,intel,true,'approved',timezone('utc',now()) from src s where not exists(select 1 from public.services t where lower(trim(t.city))=s.city and lower(trim(t.name))=lower(trim(s.name)));

select public.qa_refresh_city_seo_status(slug)
from (values('split'),('nantes'),('strasbourg'),('merida'),('san_sebastian')) v(slug);

commit;

select slug,name,verified_place_count,seo_indexable,seo_requirements
from public.qa_cities where slug in('split','nantes','strasbourg','merida','san_sebastian') order by slug;
